package com.bookeat.support.service;
import com.bookeat.support.dto.*;import com.bookeat.support.entity.*;import com.bookeat.support.enums.*;import com.bookeat.support.repository.*;import com.bookeat.support.mapper.SupportMapper;import com.bookeat.commerce.service.*;import com.bookeat.common.audit.AuditService;import com.bookeat.common.response.PageResponse;import com.bookeat.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.time.Clock;
@Service @RequiredArgsConstructor @Transactional public class SupportServiceImpl implements SupportService {
 private final SupportTicketRepository tickets;private final SupportMessageRepository messages;private final SupportMapper mapper;private final CommerceAccess access;private final IdempotencyService idempotency;private final JdbcTemplate jdbc;private final AuditService audit;private final Clock clock;
 public SupportResponses.Ticket create(UUID actor,CreatorType type,String key,SupportRequests.Create q){UUID id=idempotency.execute(actor,"support-create",key,Map.of("type",type,"request",q),()->{var t=new SupportTicket();t.setCreatedByUser(actor);t.setCreatorType(type);t.setTicketNumber("ST-"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT));t.setCategory(q.category());t.setSubject(q.subject());t.setDescription(q.description());t.setPriority(q.priority());t.setStatus(SupportStatus.OPEN);tickets.saveAndFlush(t);audit.record(actor,"SUPPORT_CREATED","SupportTicket",t.getId(),null);return t.getId();});return mapper.view(owned(actor,id,false));}
 @Transactional(readOnly=true) public PageResponse<SupportResponses.Ticket> list(UUID actor,boolean admin,int page,int size){return PageResponse.from((admin?tickets.findAll(page(page,size)):tickets.findByCreatedByUser(actor,page(page,size))).map(mapper::view));}
 @Transactional(readOnly=true) public SupportResponses.Ticket get(UUID actor,UUID id,boolean admin){return mapper.view(owned(actor,id,admin));}
 @Transactional(readOnly=true) public PageResponse<SupportResponses.Message> messages(UUID actor,UUID id,boolean admin,int page,int size){var t=owned(actor,id,admin);return PageResponse.from(messages.findByTicketId(id,PageRequest.of(page,size,Sort.by("createdAt","id"))).map(m->mapper.message(m,t.getCreatedByUser())));}
 public SupportResponses.Message message(UUID actor,UUID id,boolean admin,String key,SupportRequests.Message q){UUID mid=idempotency.execute(actor,"support-message",key,Map.of("ticket",id,"request",q),()->{lock(id);var t=owned(actor,id,admin);if(t.getStatus()==SupportStatus.CLOSED)throw new ApiException(ErrorCode.SUPPORT_STATE_INVALID);var m=new SupportMessage();m.setTicketId(id);m.setSenderUser(actor);m.setMessage(q.message());messages.saveAndFlush(m);t.setStatus(admin?(t.getCreatorType()==CreatorType.CUSTOMER?SupportStatus.WAITING_CUSTOMER:SupportStatus.WAITING_OWNER):SupportStatus.IN_PROGRESS);t.setResolvedAt(null);tickets.flush();audit.record(actor,"SUPPORT_REPLY","SupportTicket",id,null);return m.getId();});var t=owned(actor,id,admin);return mapper.message(messages.findById(mid).orElseThrow(),t.getCreatedByUser());}
 public SupportResponses.Ticket close(UUID actor,UUID id,SupportRequests.Action q){lock(id);var t=owned(actor,id,false);access.version(t.getVersion(),q.version());t.setStatus(SupportStatus.CLOSED);t.setResolvedAt(clock.instant());tickets.flush();audit.recordReason(actor,"SUPPORT_CLOSED","SupportTicket",id,q.reason());return mapper.view(t);}
 public SupportResponses.Ticket assign(UUID actor,UUID id,SupportRequests.Assign q){lock(id);var t=owned(actor,id,true);access.version(t.getVersion(),q.version());Boolean eligible=jdbc.queryForObject("select exists(select 1 from users u join user_roles ur on ur.user_id=u.id join role_permissions rp on rp.role_id=ur.role_id join permissions p on p.id=rp.permission_id where u.id=? and u.status='ACTIVE' and p.code='SUPPORT_MANAGE')",Boolean.class,q.adminId());if(!Boolean.TRUE.equals(eligible))throw new ApiException(ErrorCode.ACCESS_DENIED);if(t.getStatus()==SupportStatus.CLOSED)throw new ApiException(ErrorCode.SUPPORT_STATE_INVALID);t.setAssignedAdmin(q.adminId());t.setStatus(SupportStatus.IN_PROGRESS);tickets.flush();audit.recordReason(actor,"SUPPORT_ASSIGNED","SupportTicket",id,q.reason());return mapper.view(t);}
 public SupportResponses.Ticket status(UUID actor,UUID id,SupportRequests.Status q){lock(id);var t=owned(actor,id,true);access.version(t.getVersion(),q.version());if(t.getStatus()==SupportStatus.CLOSED&&q.status()!=SupportStatus.OPEN)throw new ApiException(ErrorCode.SUPPORT_STATE_INVALID);if(q.status()==SupportStatus.WAITING_CUSTOMER&&t.getCreatorType()!=CreatorType.CUSTOMER||q.status()==SupportStatus.WAITING_OWNER&&t.getCreatorType()!=CreatorType.OWNER)throw new ApiException(ErrorCode.SUPPORT_STATE_INVALID);t.setStatus(q.status());t.setResolvedAt(q.status()==SupportStatus.RESOLVED||q.status()==SupportStatus.CLOSED?clock.instant():null);tickets.flush();audit.recordReason(actor,"SUPPORT_STATUS_UPDATED","SupportTicket",id,q.reason());return mapper.view(t);}
 private SupportTicket owned(UUID actor,UUID id,boolean admin){return tickets.findById(id).filter(t->admin||t.getCreatedByUser().equals(actor)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));}
 private void lock(UUID id){if(jdbc.query("select id from support_tickets where id=? for update",(r,n)->r.getObject(1,UUID.class),id).isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);}
 private Pageable page(int p,int n){return PageRequest.of(p,n,Sort.by(Sort.Direction.DESC,"createdAt","id"));}
}
